# 第 4 批：卦 27-35（颐、大过、坎、离、咸、恒、遁、大壮、晋）

HEXAGRAMS = {
  "27": {"zh": "颐卦下震上艮，讲颐养之道。它讲的是怎么养自己——看人怎么养、更要自己求口粮；养的东西要正，求的要靠自己。", "en": "Yi is movement below, mountain above — the way of nourishment. It's about how to nourish yourself: observe how others nourish, but seek your own food. What you nourish must be right, and what you seek must come from yourself.", "ja": "頤は下が震、上が艮。養う道を表す。自分をどう養うか——人の養い方を見て、自分で口の実を求める。養うものは正しく、求めるのは自らに委ねる。"},
  "28": {"zh": "大过卦下巽上兑，负担过重却能渡过。它讲的是非常时期——像房梁被压弯，要用非常担当、建非常之功。", "en": "Daguo is compliance below, joy above — excessive burden yet crossing through. It's about extraordinary times: like a beam bending under load, it takes extraordinary responsibility and achievement.", "ja": "大過は下が巽、上が兑。重すぎる負担を渡る。非常の時を表す——棟が撓むような時、非常の任を負い、非常の功を立てる。"},
  "29": {"zh": "坎卦是两层坎相叠，重险。它讲的是身处险中的道理——在险里磨炼心志，只有真诚笃实的心才靠得住。", "en": "Kan is water doubled — danger upon danger. It's about being in danger: temper your heart through hardship; only a sincere, solid heart can be relied on.", "ja": "坎は重なった坎、険が重なる。険の中にいる道理を表す——険で心を鍛え、ただ真実の心だけが頼りになる。"},
  "30": {"zh": "离卦是两层离相继，附丽。它讲的是光明而能柔和——像养母牛，明而不刚，用柔来保住光明。", "en": "Li is brightness doubled — attaching and clinging. It's about clarity that stays soft: like nourishing a mother cow, bright but not rigid, preserving light through gentleness.", "ja": "離は重なった離、付き従う。明るくて柔れを保てることを表す——雌牛を養うように、明るく剛ではなく、柔で明を保つ。"},
  "31": {"zh": "咸卦下艮上兑，少男少女。它讲的是感应——咸就是感，有感就相通，但不可出于私心。", "en": "Xian is mountain below, joy above — young man and young woman. It's about response: Xian means to feel; when you feel, you connect — but not from selfish motive.", "ja": "咸は下が艮、上が兑。若い男と女。感応を表す——咸とは感ずること。感じれば通じるが、私心から出てはならない。"},
  "32": {"zh": "恒卦下巽上震，长久而常。它讲的是恒久——守住德行，久又能变，这才叫通达。", "en": "Heng is compliance below, movement above — lasting and constant. It's about endurance: hold your virtue, and being long-lasting yet able to change — that's called penetrating.", "ja": "恒は下が巽、上が震。長く続くこと。恒久の道理を表す——徳を守り、久しくて変化できる。これを通じるという。"},
  "33": {"zh": "遁卦下艮上乾，退避。它讲的是退让——看出苗头就退，潇洒地隐退无不利，退得其所。", "en": "Dun is mountain below, strength above — withdrawal. It's about stepping back: see the sign and retire; a graceful retreat brings nothing unfavorable — retreat to the right place.", "ja": "遯は下が艮、上が乾。退くこと。譲り退く道理を表す——兆しを見て退き、飄々と隠れれば不利はない。退くところを得る。"},
  "34": {"zh": "大壮卦下乾上震，刚强壮盛。它讲的是壮盛要有所节制——逞强于脚趾就进不了，公羊撞篱笆，壮而想冒进就会困住。", "en": "Dazhuang is strength below, movement above — robust strength. It's about curbing strength: showing off in the toes gets you nowhere; a ram butting the fence, strong but rushing ahead, gets stuck.", "ja": "大壮は下が乾、上が震。剛強で盛ん。壮んでも制する必要があることを表す——趾で強がれば進めず、雄羊が垣に突き当たれば、強くて進もうとして行き詰まる。"},
  "35": {"zh": "晋卦下坤上离，太阳从地面升起。它讲的是上进——自己彰显光明，前进而不乱了次序。", "en": "Jin is yielding below, clarity above — the sun rising over the earth. It's about advancing: bring out your own light, move forward without disrupting the order.", "ja": "晋は下が坤、上が離。地の上に太陽が出る。進むことを表す——自ら明らかにし、順番を乱さずに進む。"},
}

LINES = {
  # 27 颐
  "27-0": {"zh": "你在最底下，有可以养自己的本钱，却因欲望而动，舍掉了本有的。丢掉自己有的去羡慕别人有的，是自弃其养——养生的道理，先在自足。", "en": "You're at the bottom with the means to nourish yourself, but moved by desire you abandon what you have. Dropping your own to envy another's is throwing away your nourishment. Nourishment begins with self-sufficiency.", "ja": "一番下にいて、養う資があるのに欲に動かされ、持つものを捨てた。自分のものを捨てて人のものを慕うのは、養いを自ら捨てること。養う道はまず自足にある。"},
  "27-1": {"zh": "你在下卦正中，柔顺得正却向下求养于初九，反了常道。向下求养，是违背常理——下面养不了上面，去了也得不到。", "en": "You're at the center of the lower trigram, soft and proper, yet seeking nourishment below from the first line — against the normal order. Seeking below reverses the norm; the lower can't nourish the higher, so you gain nothing.", "ja": "下卦の中央にいて、柔らかく正しいが、下の初九に養いを求め、常道に反する。下に養いを求めるのは常を拂うこと。下は上を養えないので、行っても得られない。"},
  "27-2": {"zh": "你在下卦最上面，不中不正，处在变动的极点，所求的养完全悖理。不中不正还一味求人，道路已经错了——久了没人可用，是自弃。", "en": "You're at the top of the lower trigram — off-center and improper, at the peak of movement, your seeking wholly perverse. Off-center and asking only from others, your way is already wrong — in time no one will serve you; you've abandoned yourself.", "ja": "下卦の最上部にいて、中も正も外れ、動きの極にあり、求める養いが大いに悖る。中を外れてただ人に求めれば、道はすでに違っている。久しければ用いる者がいなくなる——自ら捨てたのだ。"},
  "27-3": {"zh": "你在上卦下面，柔顺得正而求养于初九，所求专一。身在上位而能向下求，是顺——求之专而且相继，所以得养而无过。", "en": "You're below the upper trigram, soft and proper, seeking nourishment from the first line — focused in your request. Being high yet seeking below is compliance; focused and continuous, you're nourished without fault.", "ja": "上卦の下にいて、柔らかく正しく初九に養いを求め、その求めは専一。上にいて下へ求められるのは順だ。求めが専で続くので、養いを得て過ちはない。"},
  "27-4": {"zh": "你身居尊位，柔和中正却向上依附九五，不能自养。居尊位而不能自养，靠贤者是可以的——守静还行，涉险济事就不行了。", "en": "You're in the place of honor, soft and centered, relying on the top line above, unable to nourish yourself. In high position yet unable to self-nourish, depending on a worthy one is acceptable — staying still works, but venturing into danger doesn't.", "ja": "尊い位にいて、柔らかく中を得て上九に従い、自ら養えない。尊くても自养できず、賢者に頼るのはよい。静を守るのはできても、険を渡ることはできない。"},
  "27-5": {"zh": "你到了卦的顶，是颐卦的主爻，天下靠你得到滋养。做别人的依靠来养人，责任重所以危险——危而能尽到责任，就能渡人。", "en": "You're at the top of the hexagram, the main line of Yi, the world relying on you for nourishment. Being what others depend on for sustenance is a heavy charge, hence danger. Dangerous yet fulfilling the charge — you can carry it through.", "ja": "卦の頂点にいて、頤の主爻となり、天下があなたによって養われる。人の頼りとなって養うのは、任が重いので危うい。危うくても任を尽くせば、人を救える。"},
  # 28 大过
  "28-0": {"zh": "你在最底下，是大过的开始，以柔承刚，谨慎又谨慎。过分谨慎也不嫌多——用柔垫在刚下，慎到极点就不会有失。", "en": "You're at the bottom, the start of Daguo, soft supporting rigid, cautious again and cautious. Excessive care is never too much — placing softness beneath strength, caution to the utmost avoids error.", "ja": "一番下にいて、大過の初め。柔で剛を承け、慎みに慎みを重ねる。過ぎた慎重さも嫌わない。柔で剛を支え、慎みの極ならば失いはない。"},
  "28-1": {"zh": "你在下卦正中，刚强却过了头，得初六的阴来调剂。刚过头而得柔相助，就能重新生出气象——过而不极端，用处就不穷尽。", "en": "You're at the center of the lower trigram, strong but excessive, helped by the yin of the first line. Strength overdone but balanced by softness can revive — excess short of extremes has endless use.", "ja": "下卦の中央にいて、剛だが過ぎ、初六の陰を得て補う。剛が過ぎて柔に救われれば、再び生き返る。過ぎても極に至らなければ、その用は尽きない。"},
  "28-2": {"zh": "你在下卦最上面，过刚又不居中，担重物就会压弯。刚过头又不得其中，就担不起重——担重的人，贵在刚而能柔。", "en": "You're at the top of the lower trigram — overly rigid, off-center — bearing a heavy load you'll bend. Strength past its mark and missing centrality can't carry weight. Those who bear burdens value strength that can be soft.", "ja": "下卦の最上部にいて、剛が過ぎて中を得ず、重い任を負えば撓む。剛が過ぎて中を失えば、重い任を負えない。重いものを負う者は、剛で柔を作えることが肝心。"},
  "28-3": {"zh": "你在上卦下面，刚强却居柔位，过而不极端，所以能隆起。以刚处柔，就担得起责任——但有责任在身就不能再分心，一分心就出吝。", "en": "You're below the upper trigram, strong in a soft place, excess short of extreme, so you rise. Strength in softness can carry the charge — but with responsibility you can't also be tied elsewhere; attachment brings regret.", "ja": "上卦の下にいて、剛で柔の位に居り、過ぎて極まらないので隆起する。剛を柔に処すれば任を勝てる。ただ任があるのに他に心を寄せてはならない。繋がれば吝が出る。"},
  "28-4": {"zh": "你身居尊位，刚强而过了头，得到上六的阴却不能长久。过极的阳，得柔而暂时兴盛，这花不会久——盛而不实，就没什么可称道的。", "en": "You're in the place of honor, strong and excessive, gaining the yin of the top line but not for long. Extreme yang, boosted by softness, flourishes only briefly — the bloom won't last. Flourishing without substance has nothing to praise.", "ja": "尊い位にいて、剛が過ぎ、上六の陰を得ても長く続かない。過ぎきった陽が柔を得てしばらく盛んになっても、その花は長くない。盛んで中身がなければ、称すべきものがない。"},
  "28-5": {"zh": "你到了卦的顶，处在大过的尽头，柔弱却冒险，以至于灭顶。才干不够还要强撑，极点就伤身——不过你的志向是济事，所以这个过可以原谅。", "en": "You're at the top of the hexagram, Daguo at its end, soft yet braving danger to the point of drowning. Ability too small yet forcing through, at the extreme you harm yourself — but your aim was to help, so the excess can be forgiven.", "ja": "卦の頂点にいて、大過の終わり。柔で険を冒し、頂まで沈む。才が足りないのに無理に済そうとし、極めて身を傷つける。ただ志は人を救うことにあるので、この過ぎは許される。"},
  # 29 坎
  "29-0": {"zh": "你在最底下，是重坎之下，陷得最深。身处重险之下又没有刚强来自拔，越陷越深——柔弱处在险中，是把自己淹死。", "en": "You're at the bottom, under the lower Kan, sunk deepest. In double danger without strength to pull yourself out, you sink further — softness in danger is drowning yourself.", "ja": "一番下にいて、重なった坎の下、最も深く陷る。重い険の下にいて剛なく自ら抜けられなければ、ますます深く沈む。柔で険に処するのは、自分を溺れさせることだ。"},
  "29-1": {"zh": "你在下卦正中，刚健中正而处在险中，可以求小小的所得。在险中而不失刚健，可以求小得——大的还做不到，小的不失操守。", "en": "You're at the center of the lower trigram, strong and centered in danger, able to gain a little. In danger without losing strength, you can seek small gains — the great isn't yet possible, but the small keeps your integrity.", "ja": "下卦の中央にいて、剛中で険にあり、小さな得を求められる。険の中にいて剛を失わなければ、小得を求められる。大きなことはまだできず、小さなことは操守を失わない。"},
  "29-2": {"zh": "你在下卦最上面，不中不正，来去都是险。进退都是险，就不能有什么作为——这时妄动，只会陷得更深。", "en": "You're at the top of the lower trigram — off-center and improper, coming and going both danger. With danger whichever way, you can't accomplish anything — rash motion now only sinks you deeper.", "ja": "下卦の最上部にいて、中も正も外れ、行き来とも険だ。進んでも引いても険なら、何も成せない。ここで妄りに動けば、かえって深く陷る。"},
  "29-3": {"zh": "你在上卦下面，柔顺得正而靠近九五，用薄礼从窗口纳诚。处险之时，礼薄而诚到，就能相通——不靠形式靠真心，所以最终能免。", "en": "You're below the upper trigram, soft and proper near the fifth line, offering a slender gift through the window. In danger, thin ceremony but genuine feeling can connect — not form but substance, so in the end you're spared.", "ja": "上卦の下にいて、柔らかく正しく九五に近く、薄い礼を窓から差し出す。険の時、礼は薄くても誠が至れば通じる。文ではなく質によるので、最終的に免れられる。"},
  "29-4": {"zh": "你身居尊位，刚健中正而处险中，水还没满，将平可出。刚中处险，险还不至于满——能把心放平等着，险自己就消了。", "en": "You're in the place of honor, strong and centered in danger, the water not yet full — about to level and flow out. Strength-centered in danger, the danger isn't brimming. Level your heart and wait, and the danger subsides by itself.", "ja": "尊い位にいて、剛中で険にあり、水はまだ満ちず、平らになろうとして出られる。剛中で険にあれば、険は満ちきらない。心を平らにして待てば、険は自ずと消える。"},
  "29-5": {"zh": "你在最上面，是坎的尽头，被险缠住出不来。处在险的极点又无法自拔，久了也解不开——柔而不知变，是自己困住自己。", "en": "You're at the top, Kan at its end, bound by danger and unable to leave. At danger's extreme with no way out, long unable to break free — soft and not knowing change, you've trapped yourself.", "ja": "一番上にいて、坎の終わり。険に繋がれて出られない。険の極にあって自ら抜けられず、久しくても解けない。柔で変化を知らないのは、自分で自分を困らせているのだ。"},
  # 30 离
  "30-0": {"zh": "你在最底下，是离的开始，动念纷杂，用恭敬来守住。火性容易乱动，初动又杂——以恭敬自持，动就不会乱。", "en": "You're at the bottom, the start of Li, your stirrings confused — hold them with reverence. Fire moves erratically and the first stirrings are mixed. Holding yourself with reverence keeps your motion ordered.", "ja": "一番下にいて、離の初め。念が入り乱れる。敬でこれを保つ。火は動きやすく、初めの動きは雑——敬をもって自らを保てば、その動きは乱れない。"},
  "30-1": {"zh": "你在下卦正中，柔顺得正而附丽，黄是中色。附丽在正中，光明就不偏——中之色正，是文明的极盛。", "en": "You're at the center of the lower trigram, soft, proper and attached, with yellow the color of the middle. Attached at the center, your light isn't skewed — the middle's color is right: the height of culture.", "ja": "下卦の中央にいて、柔らかく正しく付き従う。黄は中の色。真ん中に付けば明かりは偏らず、黄という中の色が正しい——文明の盛りだ。"},
  "30-2": {"zh": "你在下卦最上面，光明将尽之时，过了中位不会久。盛极转衰，是事物的常理——懂这个而安于常理，就不因衰而忧。", "en": "You're at the top of the lower trigram, the light about to fade, past the center and not long for this. Glory peaking then declining is the way of things — know it and rest in the norm, and you won't grieve at the decline.", "ja": "下卦の最上部にいて、明かりが尽きようとし、中を過ぎて長くは続かない。盛んさの極は衰えへ向かうのが物の常。これを知って常に安んじれば、衰えを憂えない。"},
  "30-3": {"zh": "你在上卦下面，刚强却不居中，来势突然又凶暴。刚暴而骤进，势头不会久——骤然的必折断，凶暴的必被弃。", "en": "You're below the upper trigram, strong but off-center, arriving suddenly and violently. Violent strength rushing forward won't last — the sudden snaps, the violent is cast off.", "ja": "上卦の下にいて、剛だが中を外れ、来ること突然で勢いが暴い。剛暴で急に進めば、その勢いは長くない。急なものは必ず折れ、暴いものは必ず捨てられる。"},
  "30-4": {"zh": "你身居尊位，柔和中正而附丽于刚，内心深怀忧惧不得安。居尊而能忧，忧就能戒——戒了就不至于失掉光明。", "en": "You're in the place of honor, soft and centered, attached to strength, your heart heavy with worry and unrest. In high position able to worry, worry brings caution — caution keeps you from losing your light.", "ja": "尊い位にいて、柔らかく中を得て剛に付き、心は深く憂えて安まない。尊くて憂えられる者は、憂えれば戒める。戒めれば、その明かりを失わずに済む。"},
  "30-5": {"zh": "你到了卦的顶，光明的终点，用刚明之极施用于外。明到极处就可以决断——所诛的是首恶，所不问的是胁从，这是用明的正道。", "en": "You're at the top of the hexagram, Li at its end, applying the utmost of rigid clarity outward. At the peak of clarity you can judge — punish the ringleader, leave the followers alone. That's the right use of clarity.", "ja": "卦の頂点にいて、明の終わり。剛明の極を外に用いる。明が極まれば裁ける——誅すべきは首謀者で、問わないのはその一味。これが明の正しい使い方だ。"},
  # 31 咸
  "31-0": {"zh": "你在最底下，是感的开始，所感的只是末节，心意向外。感从细微处起，动还很浅——志向虽向外，还没真正落到事上。", "en": "You're at the bottom, the start of Xian, sensing only the surface, your aim turned outward. Feeling starts small, the stirrings still shallow — your aim reaches out but hasn't touched real events.", "ja": "一番下にいて、咸の初め。感ずるのは末端だけで、志は外へ向かう。感応は微かなところから始まり、動きはまだ浅い。志は外に向かうが、まだ事には及ばない。"},
  "31-1": {"zh": "你在下卦正中，柔顺得正而感，一动就躁。所感渐深，一动就失了正——能静以自守，感应就不偏。", "en": "You're at the center of the lower trigram, soft, proper and sensing, but moving rashly. Feeling deepens, and moving loses your rightness — stay still and keep yourself, and your response won't swerve.", "ja": "下卦の中央にいて、柔らかく正しく感ずるが、動けば躁る。感ずること次第に深まり、動けば正を失う。静かに自らを守れば、その感応は偏らない。"},
  "31-2": {"zh": "你在下卦最上面，过刚又好动，随着别人走而不能自主。一心跟着别人，反而丢了主意，这叫执其随——随人而不能自主，前往就生羞。", "en": "You're at the top of the lower trigram — overly rigid and restless, following others without a will of your own. Intent on following, you lose your center — that's being held by your following. Follow without autonomy and going brings shame.", "ja": "下卦の最上部にいて、剛が過ぎて動きたがり、人に従って自ら主を持てない。ただ人に従おうとして主を失う——これを随いを執るという。従って自主できなければ、行けば恥が生まれる。"},
  "31-3": {"zh": "你在上卦下面，是心的位置、感的主宰，思虑往来不定。感应之道贵在正而专一——思虑纷纭，所感的就窄；正则大而公。", "en": "You're below the upper trigram, the seat of the heart, master of response, your thoughts coming and going. Response values being right and steadfast — scattered thinking narrows what you sense; rightness makes it broad and public.", "ja": "上卦の下にいて、心の位、感応の主。思いが行ったり来たりして定まらない。感応の道は正しく専一であることが肝心。思虑が入り乱れれば感ずる所は狭く、正しければ広く公になる。"},
  "31-4": {"zh": "你在尊位，刚健中正却感在不该感的地方，所感浅。感在背上，心意到不了人——不过你得其正，所以可以无悔。", "en": "You're in the place of honor, strong and centered, yet sensing where you shouldn't — shallow response. The feeling is on the back, your aim not reaching people — but you stay right, so you can be without regret.", "ja": "尊い位にいて、剛中で正しいが、感ずべきでない所に感ずる。感ずるのは背中で、志は人に届かない。ただ正を得ているので、悔いなくて済む。"},
  "31-5": {"zh": "你到了卦的顶，感的终点，所感的只是口舌，不是出于心。用言语去感人，是感的末流——没有真心只动嘴，不足以感人。", "en": "You're at the top of the hexagram, Xian at its end, sensing only in words, not from the heart. Moving people with talk is the dregs of response — no heart, just moving the mouth; it won't move anyone.", "ja": "卦の頂点にいて、咸の終わり。感ずるのは口舌だけで、心からではない。言葉で人を感ずるのは感応の末だ。心がなくて口だけを動かしても、人を感ずるには足りない。"},
  # 32 恒
  "32-0": {"zh": "你在最底下，是恒的开始，求之太深又不按顺序来。恒久之道贵在渐进——求得太急，这个恒就长不了。", "en": "You're at the bottom, the start of Heng, seeking too deeply and out of sequence. Endurance values gradual progress — seeking too hastily, your constancy can't last.", "ja": "一番下にいて、恒の初め。求めること深すぎて順を踏まない。恒久の道は徐々に進むことが肝心。あまりに急げば、その恒久は長く続かない。"},
  "32-1": {"zh": "你在下卦正中，刚健中正而长久守着正道。刚而得中，长久就有根——久守中道，失去的自会回来。", "en": "You're at the center of the lower trigram, strong and centered, long holding your way. Strength with centrality gives endurance a root — hold the middle way and what you lost returns.", "ja": "下卦の中央にいて、剛中でその道を長く守る。剛で中を得れば、久しさに根がある。中道を久しく守れば、失ったものは自ずと戻る。"},
  "32-2": {"zh": "你在下卦最上面，过刚又不居中，德行不能恒久。德不恒，就没人在信你——所处虽正却不能持久，羞辱就跟着来。", "en": "You're at the top of the lower trigram — overly rigid, off-center — your virtue can't endure. Virtue unsteady, no one trusts you. Though your place is right, you can't sustain it, and disgrace follows.", "ja": "下卦の最上部にいて、剛が過ぎて中を外れ、徳を恒久に保てない。徳が続かなければ人は信じない。位は正しくても長く続けられず、恥が後を追う。"},
  "32-3": {"zh": "你在上卦下面，不中不正，久留在不该久的位置。久在不该久的地方，虽久也无功——恒要守在正道上，不是光久就行。", "en": "You're below the upper trigram — off-center and improper — long staying where you shouldn't. Long in a wrong place, though long, achieves nothing. Endurance must be on the right path, not mere duration.", "ja": "上卦の下にいて、中も正も外れ、久しるべきでない所に久しくいる。久しくても功はない。恒はその道にあってこそ——ただ長ければよいのではない。"},
  "32-4": {"zh": "你在尊位，柔和中正而恒守其德，以柔顺为正。柔顺的恒，用在顺从别人是对的；但用来裁断事情，就不能一味柔了。", "en": "You're in the place of honor, soft and centered, holding your virtue — taking compliance as right. A yielding constancy is right when following others; but in deciding matters you can't be soft throughout.", "ja": "尊い位にいて、柔らかく中を得て徳を恒に守り、従顺を正とする。柔顺の恒は、人に従う者には正しい。しかし事を裁する者は、一貫して柔ではいけない。"},
  "32-5": {"zh": "你到了卦的顶，恒的终点，以动为恒，这个恒反而不恒。恒到了极点却好动，是违背所守——动个不停，就不能长久。", "en": "You're at the top of the hexagram, Heng at its end, taking motion as constancy — that constancy isn't constant. At the peak of Heng yet restless, you reverse what you held. Never-ending motion can't last.", "ja": "卦の頂点にいて、恒の終わり。動くことを恒とするが、その恒はかえって恒でない。恒の極で動きたがるのは、守るものに反すること。動きが止まなければ、長く続けられない。"},
  # 33 遁
  "33-0": {"zh": "你在最底下，是遁的尾巴，退在后面，势头已迟。退得不早，就成了尾巴——既然迟了就不能再往前，静候时机。", "en": "You're at the bottom, the tail of Dun — retreating behind, already too late. Retreating late makes you the tail. Late, you can't go further forward; wait quietly.", "ja": "一番下にいて、遯の尾。後ろに退き、すでに遅れている。早く退ばなかったので尾になった。遅れたなら、もう前へ進めない。静かに時を待つこと。"},
  "33-1": {"zh": "你在下卦正中，柔顺得正而意志坚定，志向不可夺。把志向守得像皮革捆住一样牢，外物解不开——中正而能自守，这是遁的坚定。", "en": "You're at the center of the lower trigram, soft, proper and firm — your aim can't be taken. Holding your resolve like a hide bound tight, no outside thing can loosen it. Centered and self-keeping: that's Dun's firmness.", "ja": "下卦の中央にいて、柔らかく正しく志は堅く、奪えない。志を革の束のように固く守れば、外物は解けない。中順で自ら守れる——これが遯の堅さだ。"},
  "33-2": {"zh": "你在下卦最上面，过刚又有所牵挂，不能决然退去。退却有牵挂，心就不安——所牵挂的是私情，所以不能当大事。", "en": "You're at the top of the lower trigram — overly rigid and attached — unable to retreat decisively. Retreating with attachments leaves your heart uneasy. What holds you is private feeling, so you can't handle great matters.", "ja": "下卦の最上部にいて、剛が過ぎて執わる所があり、決然と退けない。退いても執わりがあれば心は安まない。執われたのは私情なので、大事を任せられない。"},
  "33-3": {"zh": "你在上卦下面，刚强却居柔位，能割舍所好而退。有所爱好而能舍弃，这是君子的退隐——小人却沉溺所好而离不开。", "en": "You're below the upper trigram, strong in a soft place, able to give up what you love and retreat. Having attachments and letting them go — that's the gentleman's withdrawal. The small man drowns in what he loves and can't leave.", "ja": "上卦の下にいて、剛で柔の位に居り、好むものを切って退ける。好むことがあっても捨てられる——それが君子の遯だ。小人は好むものに溺れて離れられない。"},
  "33-4": {"zh": "你身居尊位，刚健中正而下应六二，是遁得其时。该退时退，又不失其中，这是遁的嘉美——功成身退。", "en": "You're in the place of honor, strong and centered, reaching down to the second line — Dun at the right time. Retiring when the time is right without losing your center: that's Dun's excellence — success achieved, then stepping back.", "ja": "尊い位にいて、剛中で六二に応じ、遯の時を得ている。退くべき時に退き、中を失わない——これが遯の嘉さだ。功を成して身を退く。"},
  "33-5": {"zh": "你到了卦的顶，遁的终点，超然远去而无所牵挂。没有牵累然后才能走远——心宽身无累，这是遁的极致。", "en": "You're at the top of the hexagram, Dun at its end, rising above and gone far without attachments. Only unencumbered can you go far — a broad heart and a body with no burden: that's the height of Dun.", "ja": "卦の頂点にいて、遯の終わり。超越して遠くへ去り、執わる所がない。執われがなければ遠くへ行ける。心が広く身に負い目がない——これが遯の極みだ。"},
  # 34 大壮
  "34-0": {"zh": "你在最底下，是壮的开始，以刚健在下躁动，进得太猛。壮显在脚趾，动还微就猛进——只信自己壮却不掂量能不能，前往就困穷。", "en": "You're at the bottom, the start of Dazhuang — strength stirring below, advancing too fast. Strength in the toes, small motion but a sudden rush — trusting your strength without weighing whether you can, going brings exhaustion.", "ja": "一番下にいて、大壮の初め。剛で下に動き、進み方が急激。強さが趾にあり、動きはまだ小さいのに急ぐ。壮を恃んで可否を計らなければ、行けば行き詰まる。"},
  "34-1": {"zh": "你在下卦正中，刚健中正而不过分，壮而得其正。刚而得中，壮就不凶暴——壮而不失正，所以可以前行。", "en": "You're at the center of the lower trigram, strong and centered without excess — strength with rightness. Strength with centrality keeps it from violence — strong yet not losing what's right, so you can go forward.", "ja": "下卦の中央にいて、剛中で過ぎず、壮俗に正を得る。剛で中を得れば、その壮は暴れない。壮で正を失わないので、進むことができる。"},
  "34-2": {"zh": "你在下卦最上面，过刚又不居中，用强壮欺凌人。以壮凌人，是小人所以困——君子不用其壮，所以能免。", "en": "You're at the top of the lower trigram — overly rigid, off-center — bullying others with strength. Bullying with might is how small men get stuck. The gentleman doesn't use his strength, so he avoids it.", "ja": "下卦の最上部にいて、剛が過ぎて中を外れ、壮で人を陵ぐ。壮で人を陵ぐのは、小人が行き詰まる所以だ。君子はその壮を用いないので、免れられる。"},
  "34-3": {"zh": "你在上卦下面，刚强却居柔位，壮而不极端，前进无阻。壮而得其道，所向无碍——关键不在力气大，而在处置得当。", "en": "You're below the upper trigram, strong in a soft place, robust but not extreme — advancing unblocked. Strength in its proper way meets no obstacle. The key isn't raw power but handling it rightly.", "ja": "上卦の下にいて、剛で柔の位に居り、壮でも極まらず、進む障害がない。壮がその道を得れば、行く先に阻むものなし。肝心なのは力の強さではなく、処し方が当たることだ。"},
  "34-4": {"zh": "你在尊位，柔和中正而不以壮自居，所以丧其壮。处壮盛之时而能自己收敛刚强，是以柔制刚——不自有其壮，所以无悔。", "en": "You're in the place of honor, soft and centered, not exalting in strength, so you lose your might. In a time of robustness, reining in your own rigidity is using softness to master strength. Not claiming your might, you have no regret.", "ja": "尊い位にいて、柔らかく中を得て壮を恃まないので、その壮を失う。壮んな時みずから剛を収めるのは、柔で剛を制することだ。壮を自分のものとしないので、悔いはない。"},
  "34-5": {"zh": "你到了卦的顶，壮的终点，进无所往、退无所据。壮极就困，进不能退不可——以艰难自处，才能有好结局。", "en": "You're at the top of the hexagram, Dazhuang at its end — nowhere to advance, nothing to fall back on. Robustness at its peak is trapped: can't go forward, can't go back. Dwell in difficulty and you can still end well.", "ja": "卦の頂点にいて、大壮の終わり。進む所なく、退く拠りもない。壮が極まれば行き詰まる——進めず退けず。艱難をもって自らを処すれば、良い終わりを得られる。"},
  # 35 晋
  "35-0": {"zh": "你在最底下，是晋的开始，想进而受挫，还没得到人信。刚开始前进不被信任，是常事——宽以自处而不躁，就能有所得。", "en": "You're at the bottom, the start of Jin — wanting to advance but checked, not yet trusted. Not being trusted at the start of advance is normal. Be generous with yourself and not rash, and you can gain.", "ja": "一番下にいて、晋の初め。進もうとして挫け、まだ人に信じられていない。進み始めて信じられないのは常のこと。寛やかに自らを処して躁がなければ、得る所がある。"},
  "35-1": {"zh": "你在下卦正中，柔顺得正而进，心里常怀忧。能进还忧，进就不苟——中正自守，福自外来而受之无愧。", "en": "You're at the center of the lower trigram, soft, proper and advancing, your heart often worried. Advancing yet worried makes your advance careful. Keep to center and rightness, and blessing comes from outside which you accept without shame.", "ja": "下卦の中央にいて、柔らかく正しく進み、心に常に憂いがある。進んで憂えれば、その進みはいい加減でない。中正を守れば、福は外から来て恥なく受けられる。"},
  "35-2": {"zh": "你在下卦最上面，被下面两个阴爻信任，与众同进。进而得众人认可，志向就行得通——悔恨消失，因为不是独自前进。", "en": "You're at the top of the lower trigram, trusted by the two yin below, advancing with the crowd. Advancing with the crowd's approval, your aim can be carried out. Regret vanishes because you don't advance alone.", "ja": "下卦の最上部にいて、下の二つの陰に信じられ、衆と共に進む。進んで衆の允を得れば、志は行われる。悔いは消える——独りで進むのではないからだ。"},
  "35-3": {"zh": "你在上卦下面，不中不正，处近君之位却不守本分。位高而德不称，像老鼠又贪又怕——守着这个不变，危险可想而知。", "en": "You're below the upper trigram — off-center and improper — near the ruler's place but not keeping your station. High position with unworthy virtue, like a rat: greedy and fearful. Hold this unchanged and the danger is plain.", "ja": "上卦の下にいて、中も正も外れ、君に近い位にいて分を守らない。位が高くて徳が釣り合わず、鼠のように貪って恐れる。これを守って変えなければ、危うさは知れている。"},
  "35-4": {"zh": "你在尊位，柔和中正而不以得失为念，前往无私。不被得失拖累心，所往皆通——无私的人，上进就大。", "en": "You're in the place of honor, soft and centered, without gain or loss on your mind, going without selfishness. When gain and loss don't burden your heart, everywhere you go opens. The selfless advance greatly.", "ja": "尊い位にいて、柔らかく中を得て得失を念にせず、行く先に私がない。得失が心を疲れさせなければ、行く所すべて通じる。私のない者は、その進みが大きい。"},
  "35-5": {"zh": "你在卦的顶，晋的终点，进无可进，作用反而在内。进到极点就返过来治理自己——讨伐私邑，是反求诸己之道。", "en": "You're at the top of the hexagram, Jin at its end — nothing further to advance, the use turns inward. At the peak of advance you return to govern yourself. Attacking your own domain is the way of seeking within.", "ja": "卦の頂点にいて、晋の終わり。進む所がなく、働きはかえって内にある。進みの極は返って自らを治める。私邑を討つのは、己に返り求める道だ。"},

}
